const ray=new THREE.Raycaster();let start=null;canvas.addEventListener('pointerdown',e=>start=[e.clientX,e.clientY]);canvas.addEventListener('pointerup',e=>{if(!ready||!start||Math.hypot(e.clientX-start[0],e.clientY-start[1])>5)return;const b=canvas.getBoundingClientRect();ray.setFromCamera(new THREE.Vector2((e.clientX-b.left)/b.width*2-1,-(e.clientY-b.top)/b.height*2+1),camera);const found=ray.intersectObjects([...objects.filter(o=>o.visible),...clothes.map(c=>c.mesh).filter(o=>o.visible)])[0];if(found){if(found.object.userData.sportswear){restoreSelection();selected=[found.object];selectedAnchor=anchorAt(found.object,found.point);showNames({userData:{female:!!found.object.userData.female,display_name_es:found.object.userData.shoe?found.object.userData.anatomical_name:'Ropa deportiva · resaltado: '+clothingTarget.selectedOptions[0].textContent,anatomical_name:found.object.userData.shoe?'Sports shoe':'Sportswear · muscle map'}});selectionBubble.hidden=false;}else choose(found.object,false,found);}});
